package cn.sifangguan.hotelaios.finance;

import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

@Service @Transactional
public class FinanceBankControlService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final FinanceOperationsService operations;private final FinanceControlGuard guard;
 public FinanceBankControlService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,FinanceOperationsService operations){this.jdbc=jdbc;this.database=database;this.access=access;this.operations=operations;guard=new FinanceControlGuard(jdbc);}
 private TenantPrincipal prepare(boolean write){if(write)access.requirePermission("finance.pay");else access.requireAnyPermission("finance.read","finance.pay");var p=access.principal();database.apply(p.tenantId());return p;}
 private Map<String,Object> account(TenantPrincipal p,UUID id){var rows=jdbc.queryForList("select * from fo_bank_account where tenant_id=:tenant and id=:id",base(p).addValue("id",id));if(rows.isEmpty())throw missing();access.requireOrgScope(id(rows.getFirst().get("hotel_id")));return rows.getFirst();}
 private Map<String,Object> load(TenantPrincipal p,UUID id,boolean lock){var r=jdbc.queryForList("select * from fc_bank_import where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));if(r.isEmpty())throw missing();account(p,id(r.getFirst().get("bank_account_id")));return r.getFirst();}
 public Map<String,Object> columns(String name,byte[] bytes){prepare(true);if(bytes.length==0||bytes.length>20*1024*1024)throw bad("文件为空或超过20MB");var table=name!=null&&name.toLowerCase(Locale.ROOT).endsWith(".csv")?FinanceMigrationParser.csv(bytes):name!=null&&name.toLowerCase(Locale.ROOT).endsWith(".xlsx")?FinanceMigrationParser.xlsx(bytes):null;if(table==null||table.isEmpty())throw bad("请选择实际CSV或XLSX文件");return Map.of("columns",table.getFirst(),"rows",Math.max(0,table.size()-1));}
 public Map<String,Object> preview(UUID request,UUID account,String filename,byte[] bytes,Map<String,String> mapping){var p=prepare(true);account(p,account);var fields=Set.of("externalId","occurredOn","direction","amount","counterparty","reference");if(!mapping.keySet().equals(fields))throw bad("必须映射流水编号、日期、方向、金额、对方、摘要六项");
  var parsed=FinanceMigrationParser.parse(filename,bytes,mapping);if(parsed.isEmpty()||parsed.size()>1000)throw bad("每批银行流水须为1至1000行");String hash=FinanceService.hash(bytes);var b=base(p).addValue("id",request).addValue("account",account).addValue("hash",hash);var existing=jdbc.queryForList("select * from fc_bank_import where tenant_id=:tenant and (id=:id or (bank_account_id=:account and file_hash=:hash))",b);
  if(!existing.isEmpty()){var old=existing.getFirst();if(!account.equals(old.get("bank_account_id"))||!hash.equals(old.get("file_hash"))||!new TreeMap<>(mapping).equals(new TreeMap<>(map(old.get("mapping")))))throw conflict("文件已按其他账户或映射预览，不覆盖原批次");return output(old);}
  var rows=new ArrayList<Map<String,Object>>();var errors=new ArrayList<Map<String,Object>>();var ids=new HashSet<String>();for(var raw:parsed){int line=Integer.parseInt(raw.remove("_row"));var messages=new ArrayList<String>();String key=raw.get("externalId");if(key.isBlank()||key.length()>160||!ids.add(key))messages.add("流水编号为空、过长或批内重复");try{LocalDate.parse(raw.get("occurredOn"));}catch(Exception e){messages.add("日期须YYYY-MM-DD");}if(!Set.of("IN","OUT").contains(raw.get("direction")))messages.add("方向须IN或OUT");try{String value=raw.get("amount");if(!value.matches("\\d{1,14}(\\.\\d{1,2})?"))throw new IllegalArgumentException();if(new BigDecimal(value).signum()<=0)throw new IllegalArgumentException();}catch(Exception e){messages.add("金额须正数且至多两位小数");}if(raw.get("counterparty").length()>160||raw.get("reference").length()>240)messages.add("对方或摘要过长");var row=new LinkedHashMap<String,Object>(raw);row.put("rowNumber",line);rows.add(row);if(!messages.isEmpty())errors.add(Map.of("row",line,"messages",messages));}
  jdbc.update("insert into fc_bank_import(id,tenant_id,bank_account_id,original_name,file_hash,mapping,rows,errors,created_by) values(:id,:tenant,:account,:name,:hash,cast(:mapping as jsonb),cast(:rows as jsonb),cast(:errors as jsonb),:actor)",b.addValue("name",filename).addValue("mapping",json(new TreeMap<>(mapping))).addValue("rows",json(rows)).addValue("errors",json(errors)));return output(load(p,request,false));}
 public Map<String,Object> detail(UUID id){return output(load(prepare(false),id,false));}
 public Map<String,Object> commit(UUID id,FinanceControlModels.ImportCommit in){var p=prepare(true);var r=load(p,id,true);if(!in.fileHash().equals(r.get("file_hash")))throw conflict("预览原件校验摘要已变化");if("COMMITTED".equals(r.get("status")))return output(r);version(r,in.expectedVersion());if(!rows(r.get("errors")).isEmpty())throw conflict("预览存在错误，整批拒绝入库，请修正源文件后重新预览");
  var lines=new ArrayList<FinanceOperationsModels.BankRow>();for(var row:rows(r.get("rows")))lines.add(new FinanceOperationsModels.BankRow(row.get("externalId").toString(),LocalDate.parse(row.get("occurredOn").toString()),row.get("direction").toString(),amount(row.get("amount")),row.get("counterparty").toString(),row.get("reference").toString()));
  operations.importBankTransactions(new FinanceOperationsModels.BankImport(id(r.get("bank_account_id")),id,lines));jdbc.update("update fc_bank_import set status='COMMITTED',version=version+1 where tenant_id=:tenant and id=:id",base(p).addValue("id",id));return output(load(p,id,false));}
 public Map<String,Object> matchClaim(UUID transaction,FinanceControlModels.ClaimMatch in){var p=prepare(true);
  // Same advisory key as FinanceOperationsService.match; supply refunds use the same key as well.
  jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,89))",Map.of("key",p.tenantId()+":bank-match"),Object.class);
  var b=base(p).addValue("id",transaction).addValue("request",in.requestId());var txs=jdbc.queryForList("select * from fo_bank_transaction where tenant_id=:tenant and id=:id",b);if(txs.isEmpty())throw missing();var bankTx=txs.getFirst();var bank=account(p,id(bankTx.get("bank_account_id")));LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));
  var old=jdbc.queryForList("select * from fc_claim_bank_match where tenant_id=:tenant and id=:request",b);if(!old.isEmpty()){var r=old.getFirst();if(!transaction.equals(r.get("transaction_id"))||!in.instructionId().equals(r.get("instruction_id"))||in.amount().compareTo(amount(r.get("amount")))!=0||!p.actorId().equals(r.get("created_by"))||!in.note().equals(r.get("note")))throw conflict("核对请求已用于不同分配");return output(r);}
  var paid=jdbc.queryForList("select * from fc_cash_instruction where tenant_id=:tenant and id=:instruction and source_kind='CLAIM' and status='EXECUTED'",base(p).addValue("instruction",in.instructionId()));if(paid.isEmpty())throw conflict("必须选择已经执行的真实报销付款指令");var instruction=paid.getFirst();access.requireOrgScope(id(instruction.get("hotel_id")));
  if(!"PAYMENT".equals(instruction.get("action"))||!"OUT".equals(bankTx.get("direction"))||!instruction.get("bank_account_id").equals(bankTx.get("bank_account_id")))throw bad("银行流水账户或方向与报销付款不符");if(bank.get("company_id")==null||!bank.get("company_id").equals(instruction.get("company_id"))||!bank.get("hotel_id").equals(instruction.get("hotel_id")))throw conflict("资金账户主体未知或与冻结付款主体不同，请先核对法人归属");if(date(bankTx,"occurred_on").isBefore(date(bank,"opening_date"))||date(bankTx,"occurred_on").isAfter(today))throw conflict("银行流水日期应在账户期初日后且已实际发生");
  var payment=jdbc.queryForList("select y.*,c.company_id from finance_payment y join finance_claim c on c.tenant_id=y.tenant_id and c.id=y.claim_id where y.tenant_id=:tenant and y.request_id=:instruction and y.claim_id=:claim and not exists(select 1 from fc_claim_loan_clear l where l.tenant_id=y.tenant_id and l.payment_id=y.id)",base(p).addValue("instruction",in.instructionId()).addValue("claim",instruction.get("source_id")));if(payment.size()!=1||!bank.get("company_id").equals(payment.getFirst().get("company_id"))||date(payment.getFirst(),"paid_on").isAfter(today))throw conflict("资金指令尚无对应同主体真实现金付款，或属于非现金抵报销，不能分配银行流水");
  BigDecimal txMatched=guard.bankAllocated(p,transaction,today);if(txMatched.add(in.amount()).compareTo(amount(bankTx.get("amount")))>0)throw conflict("核对金额超过真实银行流水净剩余余额");var effective=base(p).addValue("instruction",in.instructionId()).addValue("payment",payment.getFirst().get("id")).addValue("amount",payment.getFirst().get("amount")).addValue("day",today);BigDecimal instructionMatched=guard.table("fx_cash_correction")?jdbc.queryForObject("select fx_bank_instruction_matched_amount(:tenant,:instruction,:day)",effective,BigDecimal.class):jdbc.queryForObject("select coalesce(sum(amount),0) from fc_claim_bank_match where tenant_id=:tenant and instruction_id=:instruction",effective,BigDecimal.class);BigDecimal paidAmount=guard.table("fx_cash_correction")?jdbc.queryForObject("select fx_cash_effective_amount(:tenant,'CLAIM',:payment,:amount,:day)",effective,BigDecimal.class):amount(payment.getFirst().get("amount"));if(instructionMatched.add(in.amount()).compareTo(paidAmount)>0)throw conflict("核对金额超过报销差错冲回后的真实现金付款未匹配余额");
  jdbc.update("insert into fc_claim_bank_match(id,tenant_id,transaction_id,instruction_id,amount,note,created_by) values(:request,:tenant,:id,:instruction,:amount,:note,:actor)",b.addValue("instruction",in.instructionId()).addValue("amount",in.amount()).addValue("note",in.note()));return output(jdbc.queryForMap("select * from fc_claim_bank_match where tenant_id=:tenant and id=:request",b));}
 public Map<String,Object> statement(UUID bankId,LocalDate through){var p=prepare(false);var bank=account(p,bankId);LocalDate opening=date(bank,"opening_date");if(through.isBefore(opening))throw bad("对账日早于资金账户期初日");var b=base(p).addValue("bank",bankId).addValue("through",through).addValue("opening",opening).addValue("hotel",bank.get("hotel_id")).addValue("company",bank.get("company_id"));boolean payroll=has(p,"finance.payroll"),tax=has(p,"finance.tax");
  var transactions=jdbc.queryForList("select t.* from fo_bank_transaction t where t.tenant_id=:tenant and t.bank_account_id=:bank and t.occurred_on>=:opening and t.occurred_on<=:through order by t.occurred_on,t.id",b);BigDecimal statement=amount(bank.get("opening_balance"));var unmatched=new ArrayList<Map<String,Object>>();int overmatched=0;for(var t:transactions){BigDecimal gross=amount(t.get("amount")),matched=guard.bankAllocated(p,id(t.get("id")),through);statement=statement.add("IN".equals(t.get("direction"))?gross:gross.negate());t.put("matched_amount",matched);if(matched.signum()<0||matched.compareTo(gross)>0)overmatched++;if(!payroll&&payrollTransaction(p,id(t.get("id")))){t.put("counterparty","工资资金（明细受限）");t.put("reference","工资权限不足，摘要已隐藏");}BigDecimal missing=gross.subtract(matched);if(missing.signum()>0){var row=new LinkedHashMap<>(t);row.put("unmatched_amount",missing);unmatched.add(row);}}
  var journal=new ArrayList<Map<String,Object>>();int restricted=0,invalid=0;var facts=jdbc.queryForList("select a.id,'OPERATION' source_kind,d.id source_id,d.hotel_id,d.company_id,d.type document_type,a.action,a.amount,a.occurred_on,a.reference,a.request_id instruction_id,case when a.action in ('RECEIPT','REPAYMENT') or a.action='REFUND' and d.type is distinct from 'REVENUE' then 'IN' else 'OUT' end direction from fo_action a join fo_document d on d.tenant_id=a.tenant_id and d.id=a.document_id where a.tenant_id=:tenant and a.bank_account_id=:bank and a.action in ('PAYMENT','RECEIPT','REFUND','REPAYMENT') and a.occurred_on<=:through order by a.occurred_on,a.id",b);
  facts.addAll(jdbc.queryForList("select y.id,'CLAIM' source_kind,c.id source_id,c.hotel_id,c.company_id,'CLAIM' document_type,'PAYMENT' action,y.amount,y.paid_on occurred_on,y.reference,i.id instruction_id,'OUT' direction from finance_payment y join finance_claim c on c.tenant_id=y.tenant_id and c.id=y.claim_id join fc_cash_instruction i on i.tenant_id=y.tenant_id and i.id=y.request_id and i.source_kind='CLAIM' and i.source_id=c.id and i.status='EXECUTED' where y.tenant_id=:tenant and i.bank_account_id=:bank and y.paid_on<=:through and not exists(select 1 from fc_claim_loan_clear l where l.tenant_id=y.tenant_id and l.payment_id=y.id) order by y.paid_on,y.id",b));
  for(var fact:facts){if(date(fact,"occurred_on").isBefore(opening)&&!hasPeriodCorrection(p,fact,opening,through))continue;if((!payroll&&"PAYROLL".equals(fact.get("document_type")))||(!tax&&"TAX_TASK".equals(fact.get("document_type")))){restricted++;continue;}if(!sameEntity(bank,fact)){invalid++;continue;}appendCashFact(p,journal,fact,opening,through);}
  int unknown=jdbc.queryForObject("select count(*) from fo_action a join fo_document d on d.tenant_id=a.tenant_id and d.id=a.document_id where a.tenant_id=:tenant and d.hotel_id=:hotel and a.bank_account_id is null and a.action in ('PAYMENT','RECEIPT','REFUND','REPAYMENT') and a.occurred_on>=:opening and a.occurred_on<=:through",b,Integer.class);unknown+=jdbc.queryForObject("select count(*) from finance_payment y join finance_claim c on c.tenant_id=y.tenant_id and c.id=y.claim_id where y.tenant_id=:tenant and c.hotel_id=:hotel and y.paid_on>=:opening and y.paid_on<=:through and not exists(select 1 from fc_cash_instruction i where i.tenant_id=y.tenant_id and i.id=y.request_id and i.source_kind='CLAIM' and i.status='EXECUTED') and not exists(select 1 from fc_claim_loan_clear l where l.tenant_id=y.tenant_id and l.payment_id=y.id)",b,Integer.class);
  int unassignedBusiness=0;if(guard.table("fb_bank_match")){var business=businessCashFacts(p,bank,through);var byKey=new HashMap<String,Map<String,Object>>();for(var fact:business){byKey.put(fact.get("source_kind")+":"+fact.get("id"),fact);if(!date(fact,"occurred_on").isBefore(opening)){BigDecimal effective=jdbc.queryForObject("select fb_cash_effective_amount(:tenant,:kind,:source,:amount,:through)",base(p).addValue("kind",fact.get("source_kind")).addValue("source",fact.get("id")).addValue("amount",fact.get("amount")).addValue("through",through),BigDecimal.class);BigDecimal matched=jdbc.queryForObject("select fb_bank_matched_amount(:tenant,:kind,:source,:through)",base(p).addValue("kind",fact.get("source_kind")).addValue("source",fact.get("id")).addValue("through",through),BigDecimal.class);if(effective.compareTo(matched)>0)unassignedBusiness++;if(matched.signum()<0||matched.compareTo(effective)>0)invalid++;}}
   for(var match:jdbc.queryForList("select m.* from fb_bank_match m join fo_bank_transaction t on t.tenant_id=m.tenant_id and t.id=m.transaction_id where m.tenant_id=:tenant and t.bank_account_id=:bank and (m.created_at at time zone 'Asia/Shanghai')::date<=:through order by m.created_at,m.id",b)){var fact=byKey.get(match.get("source_type")+":"+match.get("source_id"));if(fact==null){invalid++;continue;}if((!payroll&&"PAYROLL".equals(fact.get("source_kind")))||(!tax&&"TAX".equals(fact.get("source_kind")))){restricted++;continue;}if(!sameEntity(bank,fact)){invalid++;continue;}var row=new LinkedHashMap<>(fact);row.put("id",match.get("id"));row.put("source_id",fact.get("id"));row.put("source_kind","FB_"+fact.get("source_kind"));row.put("amount",match.get("amount"));row.put("allocation_basis","EXPLICIT_BANK_MATCH_NOT_INFERRED_FROM_HOTEL");if(!date(row,"occurred_on").isBefore(opening))journal.add(row);for(var reversal:jdbc.queryForList("select id,amount,accounting_on from fb_bank_match_reversal where tenant_id=:tenant and match_id=:match and accounting_on>=:opening and accounting_on<=:through order by accounting_on,id",base(p).addValue("match",match.get("id")).addValue("opening",opening).addValue("through",through))){var reverse=new LinkedHashMap<>(row);reverse.put("id",reversal.get("id"));reverse.put("source_kind","FB_MATCH_REVERSAL");reverse.put("occurred_on",reversal.get("accounting_on"));reverse.put("amount",amount(reversal.get("amount")).negate());journal.add(reverse);}}
  }
  if(guard.table("fs_settlement"))for(var row:jdbc.queryForList("select s.id,'FS_REFUND' source_kind,s.return_id source_id,r.hotel_id,n.company_id,'REFUND' action,s.amount,s.accounting_date occurred_on,s.business_date,'IN' direction,'供应商退货退款（已有实际银行关联）' reference from fs_settlement s join fs_return r on r.tenant_id=s.tenant_id and r.id=s.return_id join fs_recognition n on n.tenant_id=r.tenant_id and n.id=r.recognition_id join fo_bank_transaction t on t.tenant_id=s.tenant_id and t.id=s.bank_transaction_id where s.tenant_id=:tenant and t.bank_account_id=:bank and s.kind='REFUND' and s.accounting_date>=:opening and s.accounting_date<=:through",b)){if(!sameEntity(bank,row)){invalid++;continue;}journal.add(row);}
  int orphan=jdbc.queryForObject("select count(*) from fc_cash_instruction i where i.tenant_id=:tenant and i.bank_account_id=:bank and i.status='EXECUTED' and i.occurred_on>=:opening and i.occurred_on<=:through and not ((i.source_kind='CLAIM' and exists(select 1 from finance_payment y where y.tenant_id=i.tenant_id and y.request_id=i.id and y.claim_id=i.source_id)) or (i.source_kind='OPERATION' and exists(select 1 from fo_action a where a.tenant_id=i.tenant_id and a.request_id=i.id and a.document_id=i.source_id)))",b,Integer.class);
  journal.sort(Comparator.comparing((Map<String,Object> row)->date(row,"occurred_on")).thenComparing(row->row.get("id").toString()));BigDecimal cash=amount(bank.get("opening_balance"));for(var row:journal)cash=cash.add("IN".equals(row.get("direction"))?amount(row.get("amount")):amount(row.get("amount")).negate());boolean comparable=bank.get("company_id")!=null&&restricted==0&&invalid==0&&unknown==0&&unassignedBusiness==0&&orphan==0;var safeBank=new LinkedHashMap<>(bank);String number=Objects.toString(safeBank.get("account_number"),"");safeBank.put("account_number",number.length()>4?"****"+number.substring(number.length()-4):"****");var result=new LinkedHashMap<String,Object>();result.put("bankAccount",safeBank);result.put("through",through);result.put("statementBalance",statement);result.put("controlledCashBalance",comparable?cash:null);result.put("visibleRegisteredCashBalance",cash);result.put("difference",comparable?statement.subtract(cash):null);result.put("unmatched",unmatched);result.put("transactions",transactions);result.put("cashJournal",journal);result.put("complete",comparable&&unmatched.isEmpty()&&overmatched==0&&statement.compareTo(cash)==0);result.put("legacyCashFactsRequiringReconciliation",unknown);result.put("unassignedBusinessCashFacts",unassignedBusiness);result.put("restrictedSourceCount",restricted);result.put("invalidEntityOrAllocationCount",invalid+overmatched);result.put("orphanInstructionCount",orphan);result.put("entityKnown",bank.get("company_id")!=null);result.put("basis","REGISTERED_REAL_CASH_AND_EXPLICIT_BANK_ASSIGNMENTS; ORIGINALS_PLUS_DATED_CORRECTIONS; OPENING_INCLUSIVE");result.put("completenessMeaning","只表示已登记来源及银行流水核对一致，不替代真实银行对账单完整性确认；缺少工资/税务授权、未知主体或账户未归属时余额及差额留空。");return output(result);
 }
 private void appendCashFact(TenantPrincipal p,List<Map<String,Object>> journal,Map<String,Object> fact,LocalDate opening,LocalDate through){if(!date(fact,"occurred_on").isBefore(opening))journal.add(new LinkedHashMap<>(fact));if(!guard.table("fx_cash_correction"))return;for(var correction:jdbc.queryForList("select id,amount,accounting_on from fx_cash_correction where tenant_id=:tenant and source_kind=:kind and source_id=:source and status='CONFIRMED' and accounting_on>=:opening and accounting_on<=:through order by accounting_on,id",base(p).addValue("kind",fact.get("source_kind")).addValue("source",fact.get("id")).addValue("opening",opening).addValue("through",through))){var row=new LinkedHashMap<>(fact);row.put("id",correction.get("id"));row.put("original_cash_id",fact.get("id"));row.put("source_kind","FX_CASH_CORRECTION");row.put("occurred_on",correction.get("accounting_on"));row.put("amount",amount(correction.get("amount")).negate());row.put("reference","独立确认资金登记差错，不执行退款");journal.add(row);}}
 private List<Map<String,Object>> businessCashFacts(TenantPrincipal p,Map<String,Object> bank,LocalDate through){if(bank.get("company_id")==null)return List.of();String sql="select m.id,'REVENUE' source_kind,e.id source_id,e.hotel_id,e.company_id,m.kind action,m.amount,m.occurred_on,m.bank_reference reference,case when m.kind='RECEIPT' then 'IN' else 'OUT' end direction from fb_revenue_movement m join fb_revenue_entry e on e.tenant_id=m.tenant_id and e.id=m.entry_id where m.tenant_id=:tenant and e.hotel_id=:hotel and e.company_id=:company and m.kind in ('RECEIPT','REFUND') and m.occurred_on<=:through";sql+=" union all select y.id,'PAYROLL',b.id,b.hotel_id,b.company_id,'PAYMENT',y.amount,y.occurred_on,y.bank_reference,'OUT' from fb_payroll_payment y join fb_payroll_line l on l.tenant_id=y.tenant_id and l.id=y.line_id join fb_payroll_batch b on b.tenant_id=l.tenant_id and b.id=l.batch_id where y.tenant_id=:tenant and b.hotel_id=:hotel and b.company_id=:company and y.occurred_on<=:through";sql+=" union all select c.id,'OPENING',c.subledger_id,c.hotel_id,c.company_id,c.kind,c.amount,c.occurred_on,c.bank_reference,case when c.kind='RECEIPT' then 'IN' else 'OUT' end from fb_opening_clearing c where c.tenant_id=:tenant and c.hotel_id=:hotel and c.company_id=:company and c.occurred_on<=:through";sql+=" union all select c.id,'INTERCOMPANY',c.transaction_id,c.hotel_id,c.company_id,c.kind,c.amount,c.occurred_on,c.bank_reference,case when c.kind='RECEIPT' then 'IN' else 'OUT' end from fb_intercompany_settlement c where c.tenant_id=:tenant and c.hotel_id=:hotel and c.company_id=:company and c.occurred_on<=:through";if(guard.table("ft_tax_payment"))sql+=" union all select y.id,'TAX',y.accrual_id,y.hotel_id,y.company_id,'PAYMENT',y.amount,y.occurred_on,'实际已关联税款OUT流水','OUT' from ft_tax_payment y where y.tenant_id=:tenant and y.hotel_id=:hotel and y.company_id=:company and y.occurred_on<=:through";return jdbc.queryForList(sql,base(p).addValue("hotel",bank.get("hotel_id")).addValue("company",bank.get("company_id")).addValue("through",through));}
 private boolean hasPeriodCorrection(TenantPrincipal p,Map<String,Object> fact,LocalDate opening,LocalDate through){return guard.table("fx_cash_correction")&&Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from fx_cash_correction where tenant_id=:tenant and source_kind=:kind and source_id=:source and status='CONFIRMED' and accounting_on>=:opening and accounting_on<=:through)",base(p).addValue("kind",fact.get("source_kind")).addValue("source",fact.get("id")).addValue("opening",opening).addValue("through",through),Boolean.class));}
 private boolean payrollTransaction(TenantPrincipal p,UUID tx){var b=base(p).addValue("tx",tx);if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from fo_bank_match m join fo_action a on a.tenant_id=m.tenant_id and a.id=m.action_id join fo_document d on d.tenant_id=a.tenant_id and d.id=a.document_id where m.tenant_id=:tenant and m.transaction_id=:tx and d.type='PAYROLL')",b,Boolean.class)))return true;return guard.table("fb_bank_match")&&Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from fb_bank_match where tenant_id=:tenant and transaction_id=:tx and source_type='PAYROLL')",b,Boolean.class));}
 private static boolean sameEntity(Map<String,Object> bank,Map<String,Object> fact){return bank.get("company_id")!=null&&bank.get("company_id").equals(fact.get("company_id"))&&bank.get("hotel_id").equals(fact.get("hotel_id"));}
 private static boolean has(TenantPrincipal p,String code){return p.hasPermission("*")||p.hasPermission(code);}
 private static LocalDate date(Map<String,Object> row,String key){Object value=row.get(key);return value instanceof java.sql.Date day?day.toLocalDate():LocalDate.parse(value.toString());}
}
